import { after } from 'next/server';
import { headers } from 'next/headers';

export default async function Home() {
  // Read request data during the render phase — required before using `after`
  // in a Server Component, as Dynamic APIs cannot be called inside the callback.
  const headersList = await headers();
  const userAgent = headersList.get('user-agent') ?? 'unknown';
  const referer = headersList.get('referer') ?? null;

  // Schedule analytics logging after the response is sent — does not block rendering.
  after(async () => {
    await logPageView({ userAgent, referer, path: '/' });
  });

  return (
    <main>
      <h1>Welcome</h1>
      <p>Thanks for visiting. Page view has been logged asynchronously.</p>
    </main>
  );
}

async function logPageView(event: {
  userAgent: string;
  referer: string | null;
  path: string;
}) {
  // Replace this with your real analytics service call (e.g. fetch to an ingest endpoint).
  console.log('[analytics] page_view', {
    path: event.path,
    userAgent: event.userAgent,
    referer: event.referer,
    timestamp: new Date().toISOString(),
  });
}

